"use client";

import Image from "next/image";
import Link from "next/link";
import { useParams } from "next/navigation";
import { formatPrice, MOCK_PRODUCTS } from "../../data/mock-products";

export default function ProductDetailPage() {
  const params = useParams<{ id: string }>();
  const id = Number(params?.id);
  const product = MOCK_PRODUCTS.find((p) => p.id === id);

  if (!product) {
    return (
      <div className="mx-auto flex min-h-screen max-w-3xl flex-col items-center justify-center gap-3 bg-[var(--background)] px-4 py-6 text-center">
        <p className="text-lg font-semibold text-[var(--foreground)]">
          Không tìm thấy sản phẩm
        </p>
        <Link
          href="/products"
          className="text-sm font-medium text-[var(--primary)] underline-offset-4 hover:underline"
        >
          Quay lại danh sách sản phẩm
        </Link>
      </div>
    );
  }

  return (
    <div className="mx-auto flex min-h-screen max-w-4xl flex-col gap-6 bg-[var(--background)] px-4 py-6">
      <header className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="relative h-20 w-20 overflow-hidden rounded-lg border border-[var(--border)] bg-white shadow-inner">
            <Image
              src={product.thumbnail}
              alt={product.name}
              fill
              sizes="80px"
              className="object-cover"
            />
          </div>
          <div>
            <h1 className="text-xl font-semibold tracking-tight text-[var(--foreground)]">
              {product.name}
            </h1>
            <p className="mt-1 text-xs text-[var(--muted-foreground)]">
              {product.variations.length} phân loại • Demo data
            </p>
          </div>
        </div>
        <Link
          href="/products"
          className="rounded-full border border-[var(--border)] bg-white px-3 py-1.5 text-xs font-medium text-[var(--foreground)] shadow-sm transition hover:border-[var(--primary)]/60 hover:bg-[var(--primary)]/5"
        >
          Quay lại danh sách
        </Link>
      </header>

      <main className="rounded-xl border border-[var(--border)] bg-white p-4 shadow-sm sm:p-6">
        <h2 className="text-sm font-semibold text-[var(--foreground)]">
          Biến thể sản phẩm
        </h2>
        <p className="mt-1 text-xs text-[var(--muted-foreground)]">
          Danh sách các combinations size/màu (variations) demo cho sản phẩm
          này.
        </p>

        <div className="mt-4 overflow-x-auto">
          <table className="min-w-full border-collapse text-sm">
            <thead>
              <tr className="border-b border-[var(--border)] bg-[var(--muted)]/60">
                <th className="px-4 py-2.5 text-left font-medium text-[var(--foreground)]">
                  Biến thể
                </th>
                <th className="px-4 py-2.5 text-right font-medium text-[var(--foreground)]">
                  Giá
                </th>
                <th className="px-4 py-2.5 text-right font-medium text-[var(--foreground)]">
                  Tồn kho
                </th>
              </tr>
            </thead>
            <tbody>
              {product.variations.map((v, i) => (
                <tr
                  key={v.id}
                  className={`border-b border-[var(--border)]/80 last:border-b-0 ${
                    i % 2 === 1 ? "bg-[var(--muted)]/20" : ""
                  }`}
                >
                  <td className="px-4 py-2.5 text-[var(--foreground)]">
                    {v.name}
                  </td>
                  <td className="px-4 py-2.5 text-right tabular-nums text-[var(--foreground)]">
                    {formatPrice(v.price)}
                  </td>
                  <td className="px-4 py-2.5 text-right tabular-nums text-[var(--muted-foreground)]">
                    {v.stock}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}

